const ldap = require('nuclei/ldap');

// 636 and 3269 (AD global catalog) are implicit TLS. 389 and 3268 are
// plaintext with an optional StartTLS upgrade, which cfg.Upgrade requests.
const tlsPorts = ['636', '3269'];

function tryPort(port) {
    const scheme = tlsPorts.indexOf(String(port)) !== -1 ? 'ldaps://' : 'ldap://';
    const cfg = new ldap.Config();
    // The module ignores Upgrade when the scheme is already ldaps.
    cfg.Upgrade = true;
    const client = new ldap.Client(scheme + Host + ':' + port, Realm, cfg);
    client.Authenticate('', '');
    return client.CollectMetadata();
}

// Honour the scanned port when there is one, otherwise cover the common pair.
const ports = TargetPort ? [TargetPort] : ['389', '636'];

for (let i = 0; i < ports.length; i++) {
    try {
        const metadata = tryPort(ports[i]);
        if (metadata) {
            Export(metadata);
            break;
        }
    } catch (e) {
        // port closed, wrong scheme, or bind refused - try the next one
    }
}
